DROP TABLE IF EXISTS `academic_settings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `academic_settings` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `academic_year` varchar(20) NOT NULL COMMENT 'e.g., 2024-2025',
  `semester` varchar(50) NOT NULL COMMENT '1st Semester, 2nd Semester, Summer',
  `exam_period` varchar(20) NOT NULL COMMENT 'Prelim, Midterm, Final',
  `exam_period_start` date DEFAULT NULL COMMENT 'Start date of exam period (e.g., 2026-02-09)',
  `exam_period_end` date DEFAULT NULL COMMENT 'End date of exam period (e.g., 2026-02-14)',
  `available_semesters` varchar(100) NOT NULL DEFAULT '1st Semester,2nd Semester' COMMENT 'Comma-separated list of available semesters',
  `schedule_start_hour` int(11) NOT NULL DEFAULT 7 COMMENT 'Class schedule start hour (0-23)',
  `schedule_end_hour` int(11) NOT NULL DEFAULT 20 COMMENT 'Class schedule end hour (0-23)',
  `exam_start_hour` int(11) NOT NULL DEFAULT 7 COMMENT 'Exam schedule start hour (0-23)',
  `exam_end_hour` int(11) NOT NULL DEFAULT 17 COMMENT 'Exam schedule end hour (0-23)',
  `exam_lunch_start` time NOT NULL DEFAULT '12:00:00' COMMENT 'Exam lunch break start time',
  `exam_lunch_end` time NOT NULL DEFAULT '13:00:00' COMMENT 'Exam lunch break end time',
  `exam_slot_duration` int(11) NOT NULL DEFAULT 30 COMMENT 'Exam time slot duration in minutes (30, 60, 90, 120)',
  `exam_duration_limit` int(11) NOT NULL DEFAULT 120 COMMENT 'Maximum exam duration in minutes (e.g., 120 = 2 hours)',
  `default_faculty_max_units` int(11) NOT NULL DEFAULT 24 COMMENT 'Default maximum teaching units for faculty',
  `operation_days` varchar(255) NOT NULL DEFAULT 'Monday,Tuesday,Wednesday,Thursday,Friday,Saturday' COMMENT 'Comma-separated list of operation days for scheduling',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `schedule_start_time` time NOT NULL DEFAULT '07:00:00' COMMENT 'Class schedule start time (HH:MM)',
  `schedule_end_time` time NOT NULL DEFAULT '20:00:00' COMMENT 'Class schedule end time (HH:MM)',
  `exam_start_time` time NOT NULL DEFAULT '07:00:00' COMMENT 'Exam schedule start time (HH:MM)',
  `exam_end_time` time NOT NULL DEFAULT '17:00:00' COMMENT 'Exam schedule end time (HH:MM)',
  `smart_max_backtracks_per_subject` int(11) NOT NULL DEFAULT 3 COMMENT 'Smart scheduler per-subject backtrack limit',
  `smart_max_total_backtracks` int(11) NOT NULL DEFAULT 50 COMMENT 'Smart scheduler total backtrack limit',
  `smart_timeout_seconds` int(11) NOT NULL DEFAULT 30 COMMENT 'Smart scheduler timeout in seconds',
  PRIMARY KEY (`id`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_academic_year` (`academic_year`,`semester`)
) ENGINE=InnoDB AUTO_INCREMENT=77 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
