--
-- Table structure for table `exam_schedules`
--

DROP TABLE IF EXISTS `exam_schedules`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `exam_schedules` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `section_id` int(11) NOT NULL,
  `subject_id` int(11) NOT NULL,
  `faculty_id` int(11) DEFAULT NULL,
  `room_id` int(11) DEFAULT NULL,
  `exam_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `semester` varchar(50) DEFAULT NULL COMMENT '1st Semester, 2nd Semester, Summer',
  `academic_year` varchar(20) DEFAULT NULL COMMENT 'e.g., 2024-2025',
  `exam_period` varchar(20) DEFAULT NULL COMMENT 'Prelim, Midterm, Final',
  `schedule_type` varchar(20) DEFAULT 'lecture' COMMENT 'lecture, lab',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `version` int(11) NOT NULL DEFAULT 1 COMMENT 'Optimistic locking version number',
  `locked_by` int(11) DEFAULT NULL COMMENT 'User ID currently editing this exam schedule',
  `locked_at` datetime DEFAULT NULL COMMENT 'Timestamp when lock was acquired',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_exam_section_slot` (`section_id`,`exam_date`,`start_time`,`end_time`,`academic_year`,`semester`,`exam_period`),
  KEY `section_id` (`section_id`),
  KEY `subject_id` (`subject_id`),
  KEY `faculty_id` (`faculty_id`),
  KEY `room_id` (`room_id`),
  KEY `idx_exam_date_time` (`exam_date`,`start_time`,`end_time`),
  KEY `idx_exam_locked_by` (`locked_by`),
  KEY `idx_exam_active` (`is_active`),
  KEY `idx_exam_academic` (`academic_year`,`semester`,`exam_period`),
  CONSTRAINT `exam_schedules_ibfk_1` FOREIGN KEY (`section_id`) REFERENCES `sections` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exam_schedules_ibfk_2` FOREIGN KEY (`subject_id`) REFERENCES `subjects` (`id`) ON DELETE CASCADE,
  CONSTRAINT `exam_schedules_ibfk_3` FOREIGN KEY (`faculty_id`) REFERENCES `faculty` (`id`) ON DELETE SET NULL,
  CONSTRAINT `exam_schedules_ibfk_4` FOREIGN KEY (`room_id`) REFERENCES `rooms` (`id`) ON DELETE SET NULL,
  CONSTRAINT `exam_schedules_ibfk_5` FOREIGN KEY (`locked_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=1717 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
