DROP TABLE IF EXISTS `programs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `programs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `program_code` varchar(20) NOT NULL,
  `program_name` varchar(200) NOT NULL,
  `department_id` int(11) DEFAULT NULL COMMENT 'FK to colleges table',
  `program_logo` varchar(255) DEFAULT NULL COMMENT 'Path to department logo image',
  `year_levels` int(11) NOT NULL DEFAULT 4 COMMENT 'Number of year levels in the program (e.g., 4 for BSCS, 2 for ACT)',
  `shared_program_code` varchar(50) DEFAULT NULL COMMENT 'Code of program this department shares with (e.g., ACT)',
  `shared_until_year` int(11) DEFAULT NULL COMMENT 'Year level up to which sections use shared program code (e.g., 2)',
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_archived` tinyint(1) NOT NULL DEFAULT 0,
  `archived_by` int(11) DEFAULT NULL,
  `archived_at` datetime DEFAULT NULL,
  `archive_reason` varchar(255) DEFAULT NULL,
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_program_code` (`program_code`),
  KEY `idx_is_archived` (`is_archived`),
  KEY `archived_by` (`archived_by`),
  KEY `department_id` (`department_id`),
  CONSTRAINT `programs_ibfk_1` FOREIGN KEY (`archived_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `programs_ibfk_department` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
