DROP TABLE IF EXISTS `schedule_snapshots`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `schedule_snapshots` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `snapshot_name` varchar(100) NOT NULL,
  `academic_year` varchar(20) NOT NULL,
  `semester` varchar(50) NOT NULL,
  `snapshot_scope` varchar(20) NOT NULL,
  `section_id` int(11) DEFAULT NULL,
  `schedule_data` longtext NOT NULL,
  `schedule_count` int(11) NOT NULL,
  `snapshot_type` varchar(30) NOT NULL,
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime NOT NULL,
  `notes` text DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `section_id` (`section_id`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `schedule_snapshots_ibfk_1` FOREIGN KEY (`section_id`) REFERENCES `sections` (`id`) ON DELETE SET NULL,
  CONSTRAINT `schedule_snapshots_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=26 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
