DROP TABLE IF EXISTS `users`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `username` varchar(80) NOT NULL,
  `email` varchar(120) NOT NULL,
  `password_hash` varchar(256) NOT NULL,
  `role` varchar(20) NOT NULL COMMENT 'admin or dean',
  `full_name` varchar(100) NOT NULL,
  `is_active` tinyint(1) NOT NULL DEFAULT 1,
  `is_archived` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Soft delete flag for archive pattern',
  `archived_by` int(11) DEFAULT NULL COMMENT 'User who archived this account',
  `archived_at` datetime DEFAULT NULL COMMENT 'When the account was archived',
  `archive_reason` varchar(255) DEFAULT NULL COMMENT 'Reason for archiving the account',
  `email_verified` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Whether email has been verified/setup completed',
  `email_verified_at` datetime DEFAULT NULL COMMENT 'When email was verified',
  `needs_password_change` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Force password change on next login',
  `two_factor_enabled` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'Whether TOTP two-factor authentication is enabled',
  `two_factor_secret` varchar(64) DEFAULT NULL COMMENT 'Base32 secret used for TOTP verification',
  `two_factor_enabled_at` datetime DEFAULT NULL COMMENT 'When two-factor authentication was enabled',
  `text_size` int(11) NOT NULL DEFAULT 100 COMMENT 'User preferred text size percentage (70-150)',
  `dark_mode` tinyint(1) NOT NULL DEFAULT 0 COMMENT 'User preferred dark mode (0=light, 1=dark)',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT NULL ON UPDATE current_timestamp(),
  `last_login` datetime DEFAULT NULL,
  `force_logout_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `username` (`username`),
  UNIQUE KEY `email` (`email`),
  KEY `idx_is_archived` (`is_archived`),
  KEY `idx_archived_by` (`archived_by`),
  CONSTRAINT `users_ibfk_archived_by` FOREIGN KEY (`archived_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
